    ws = wb.active
    for row in rows:
        ws.append(row)
    wb.save(path)
    return path


def _pdf_escape(text):
    return text.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def _build_pdf_page_content(lines):
    """Build the content stream for a single PDF page given a list of
    text lines to render, starting near the top of a letter-size page."""
    y = 750
    parts = ["BT", "/F1 12 Tf"]
    first = True
    for line in lines:
        if first:
            parts.append(f"50 {y} Td")
            first = False
        else:
            parts.append("0 -15 Td")
        parts.append(f"({_pdf_escape(line)}) Tj")
    parts.append("ET")
    return "\n".join(parts)


def export_pdf(rows, path):
