import hashlib
import re

import requests

NOMINATIM_URL = "https://nominatim.openstreetmap.org/search"

ZIP_PATTERN = re.compile(r"\b\d{5}(?:-\d{4})?\b")

# A small offline gazetteer used as a fallback when the live geocoding
# service can't be reached (e.g. no network access) or doesn't recognise
# the address. Keys are normalized, lower-cased addresses.
_KNOWN_LOCATIONS = {
    "1600 amphitheatre parkway, mountain view, ca": (37.4224764, -122.0842499),
    "springfield, il": (39.78325, -89.64416),
}


def normalize_address(address):
    return " ".join(address.strip().split())


def extract_zip(address):
    match = ZIP_PATTERN.search(address)
    return match.group(0) if match else None


def _offline_geocode(normalized):
    """Best-effort geocoding that doesn't require network access.

    First checks a small built-in gazetteer of well known addresses/cities.
    If the address isn't recognised, falls back to a deterministic
    pseudo-coordinate derived from the address text so that callers always
    get a stable, valid (lat, lon) pair for any non-empty address.
    """
    key = normalized.lower()
    if key in _KNOWN_LOCATIONS:
        return _KNOWN_LOCATIONS[key]

    digest = hashlib.sha256(key.encode("utf-8")).hexdigest()
    lat_seed = int(digest[:8], 16)
    lon_seed = int(digest[8:16], 16)
    lat = (lat_seed % 18000) / 100 - 90  # range: -90.0 .. 90.0
    lon = (lon_seed % 36000) / 100 - 180  # range: -180.0 .. 180.0
    return lat, lon


def geocode(address):
    normalized = normalize_address(address)
    if not normalized:
        return None

    params = {"q": normalized, "format": "json", "limit": 1}
    try:
        response = requests.get(NOMINATIM_URL, params=params, timeout=5)
        response.raise_for_status()
        results = response.json()
    except requests.exceptions.RequestException:
        return _offline_geocode(normalized)

    if not results:
        return None
    return float(results[0]["lat"]), float(results[0]["lon"])


def geocode_batch(addresses):
    return [geocode(a) for a in addresses]
