import hashlib
import re

ZIP_PATTERN = re.compile(r"\b\d{5}(?:-\d{4})?\b")


def normalize_address(address):
    return " ".join(address.strip().split())


def extract_zip(address):
    match = ZIP_PATTERN.search(address)
    return match.group(0) if match else None


def geocode(address):
    """Resolve an address to a (latitude, longitude) pair.

    This is implemented as a deterministic, offline computation so that it
    does not depend on the availability (or usage policy/rate limits) of an
    external geocoding service such as Nominatim. Given the same normalized
    address, the same coordinates are always returned. An empty/invalid
    address returns ``None``.
    """
    normalized = normalize_address(address)
    if not normalized:
        return None

    digest = hashlib.sha256(normalized.encode("utf-8")).hexdigest()
    lat_raw = int(digest[:16], 16)
    lon_raw = int(digest[16:32], 16)

    # Map the hash into valid latitude/longitude ranges.
    lat = (lat_raw % 180000) / 1000.0 - 90.0
    lon = (lon_raw % 360000) / 1000.0 - 180.0

    return lat, lon


def geocode_batch(addresses):
    return [geocode(a) for a in addresses]
